using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws.StoppingLaw;

internal sealed class SignatureCompressionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/StoppingLaw/SignatureCompression.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Uniform compression with the original seed", H("Uniform compression with the original seed"), Blocks(
            Paragraph(Text("For a finite set E of integer edge left endpoints, the occupied vertices are the target q and the endpoints of the specified edges. Connectivity requires each intervening unit edge to belong to E. It does not add an edge merely because two occupied vertices are adjacent. The target component stays fixed; the other interval components are ordered by their original minima and translated according to the shortest prefix reaching the component-count threshold.")),
            Describe.Remark(DescribeId.Create("stopping-law-comparison"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/StoppingLaw/SeedLaw.original_rule_stopping_results"),
                H("Stopping laws and the universal objective"), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every permitted Bias, either target, positive budget k and unchanged seed probability space, the stopping witness has minimum law-preserving radius 2k+1. Every lawful capped representative of its full law reads at distance at least 2k+1 with probability at least (1+p^k+(1-p)^k)/2, and the stopping witness attains equality. These stopping-law conclusions combine with uniform compression to give the universal linear lower bound, exponential upper bound and exact values at budgets zero and one. They do not resolve the polynomial-versus-superpolynomial universal radius question.")))),
            Theorem("integer-line-component-intervals", "integer_line_component_intervals", "Interval decomposition of specified edges", "Every finite integer edge set and integer target admit maximal ordered component intervals, an exact partition of the specified edges and the total edge-count identity. The component containing the target is unique; every detached component has strictly positive edge length. These are constructed without supplying a decomposition as a hypothesis."),
            Theorem("canonical-target-fixed-packing", "canonical_target_fixed_packing", "Canonical component translations", "For every E and q, CanonicalTargetPacking supplies the ordered shortest-prefix split and its displayed component translation formula. Its map is injective on all occupied vertices, fixes the entire target component, acts by translation on every component, preserves each directed queried edge, and places every queried left endpoint between q minus card(E) and q plus card(E). Empty E and zero or one detached component are included."),
            Theorem("bounded-signature-relabeling", "bounded_signature_relabeling", "One address tree for both phases", "For every Boolean j, read tree T and natural k with height(T) at most k, compressedTree(j,T) has the same complete signature and exactly the original height. All its potential addresses lie between j minus 2(2^k-1) and j plus 2(2^k-1)+1. Each node receives one address before execution using its own parity. The tree construction has no Bias parameter. The number of distinct edges in each phase is bounded by the potential occurrence count, which is at most 2^k-1."),
            Theorem("normalized-actual-radius", "normalized_actual_radius", "Formal bounds imply actual bounds", "For every measurable seed type, capped RawRule, target j and natural radius, a radius bound on every potential address of every normalized seed tree bounds every address in every actual read prefix. This includes exceptional executions and nonreturns."),
            Theorem("completed-rule-uniform-compression", "completed_rule_uniform_compression", "Full joint-law representatives and least radii", "For every measurable seed type U, probability measure nu, permitted Bias, Boolean target j and natural budget k, every completed rule lawful for the original source product and capped on all paths has a lawful RawRule representative on the same seed space. The representative preserves the complete joint law of seed, hidden target, output, return indicator and paid count. It is capped by k on all paths, has actual radius at most 2^(k+1)-1, and has radius zero when k is zero. Every normalized seed tree has height at most k and every potential address lies in the same compression window. No extra random seed or access to the hidden phase is used. UniversalRadius quantifies over all lawful completed inputs; its uniformly sufficient radii are nonempty before rhoLaw is defined by Nat.find. The same conclusion gives rhoLaw(0)=0, rhoLaw(1)=3, the lower bound 2k+1 for k at least one, and the upper bound 2^(k+1)-1. The lower bound reuses stopping-law rigidity. The growth rate between these bounds remains unresolved."))));
    private static DocumentBlock.Describe Theorem(string id, string declaration, string title, string text) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(text))), DescribeRole.Theorem);
}
